Write only `specification/project-conformance.md`. It declares a minimal CLI Hello World software-build traversal and states:
- Intent: a Node CLI that greets the user.
- Product boundary: a single script, `generated/hello-world.mjs`, run with `node` with no package installation and no network dependency. Supplied component and UAT tests are verifiers.
- Source-grounded requirements, each traced to `source/original-basic-cli.txt`:
  - the source surface is `generated/hello-world.mjs`;
  - it must run under node without package installation;
  - it must write exactly `Hello, world!\n` to stdout and exit 0;
  - both the component and UAT tests spawn `node generated/hello-world.mjs` from the project root and assert status 0 and exact stdout.
- Completion criteria:
  - executing the CLI shows exact stdout `Hello, world!\n` with exit status 0;
  - `node --test test/component/hello-cli.test.mjs test/uat/hello-cli.uat.test.mjs` shows at least 2 passes and `fail 0`;
  - execution evidence is truthful, admitted evidence (real command, args, cwd, env, status, stdout, stderr), not a prewritten report;
  - the implementation design, test design and execution plan are present and faithful.

The file may cite the current admitted observations (baseline failure 6514754a, correction e897db22, current passing run db34d3cf) as context only. It must not declare the obligations met. Do not write source, tests, package files or execution plans.

input.command:
node --input-type=module -e '
import { readFileSync } from "node:fs";
import assert from "node:assert/strict";
const p = JSON.parse(readFileSync("test-execution-plan.json","utf8"));
assert.equal(p.command, "node");
assert.deepEqual(p.args, ["--test","test/component/hello-cli.test.mjs","test/uat/hello-cli.uat.test.mjs"]);
assert.ok(Number.isInteger(p.expectedTestPassCount) && p.expectedTestPassCount >= 2);
assert.ok(p.expectedStdoutMatch.includes("fail 0"));
assert.ok(!/pass \d/.test(p.expectedStdoutMatch));
assert.equal(p.assertedReturnValue, "Hello, world!");
assert.equal(p.cliCheck.expectedStdout, p.assertedReturnValue + "\n");
assert.equal(Buffer.byteLength(p.cliCheck.expectedStdout), p.cliCheck.expectedStdoutByteLength);
const post = "✔ CLI process satisfies its output contract (25.308042ms)\n✔ a user receives the exact promised greeting (25.320375ms)\nℹ tests 2\nℹ suites 0\nℹ pass 2\nℹ fail 0\nℹ cancelled 0\nℹ skipped 0\nℹ todo 0\nℹ duration_ms 60.277041\n";
const base = "✖ CLI process satisfies its output contract (25.371083ms)\n✖ a user receives the exact promised greeting (25.168375ms)\nℹ tests 2\nℹ suites 0\nℹ pass 0\nℹ fail 2\n";
const judge = (exit, out, cliExit, cliOut) => {
  const pass = Number(/(?:ℹ|#) pass (\d+)/.exec(out)[1]);
  const fail = Number(/(?:ℹ|#) fail (\d+)/.exec(out)[1]);
  const named = p.requiredPassingTests.every(t => out.includes("✔ " + t.name) || new RegExp("^ok \\d+ - " + t.name, "m").test(out));
  const planSatisfied = out.includes(p.expectedStdoutMatch) && fail === p.expectedFailCount && named && cliExit === 0 && cliOut === p.cliCheck.expectedStdout && cliOut.slice(0,-1) === p.assertedReturnValue;
  return { pass, fail, named, planSatisfied, accept: exit === 0 && pass >= p.expectedTestPassCount && planSatisfied };
};
console.log("post-correction admitted:", JSON.stringify(judge(0, post, 0, "Hello, world!\n")));
console.log("baseline admitted:       ", JSON.stringify(judge(1, base, 0, "Hello world!\n")));
console.log("plan predicates OK");
' && shasum -a 256 source/original-basic-cli.txt source/basic-cli.oracle.json source/witness-contract.md test/component/hello-cli.test.mjs test/uat/hello-cli.uat.test.mjs generated/hello-world.mjs specification/project-conformance.md design/implementation-design.md design/test-design.md test-execution-plan.json && ls -la design

node -e '
const fs=require("fs"),c=require("crypto");
const b=fs.readFileSync("source/witness-contract.md");
for (const [s,e] of [[1228,1310],[1373,1452],[1536,1612],[1692,1769],[2270,2347],[2631,2711]]) {
  const sl=b.subarray(s,e);
  console.log(`[${s}-${e}] sha256:${c.createHash("sha256").update(sl).digest("hex").slice(0,16)}… ${JSON.stringify(sl.toString())}`);
}
for (const t of ["Hello, world!\n","Hello world!\n"]) console.log(JSON.stringify(t), Buffer.byteLength(t), c.createHash("sha256").update(t).digest("hex"));
console.log("cli bytes", fs.readFileSync("generated/hello-world.mjs").length);
const p=JSON.parse(fs.readFileSync("test-execution-plan.json","utf8"));
console.log("plan ok:", p.command==="node", JSON.stringify(p.args)===JSON.stringify(["--test","test/component/hello-cli.test.mjs","test/uat/hello-cli.uat.test.mjs"]), Number.isInteger(p.expectedTestPassCount)&&p.expectedTestPassCount>=2, p.expectedStdoutMatch.includes("fail 0"), !/pass \d/.test(p.expectedStdoutMatch), p.assertedReturnValue==="Hello, world!", p.cliCheck.expectedStdout==="Hello, world!\n", p.cliCheck.expectedStdout===p.assertedReturnValue+"\n");
